function setup() {
  createCanvas(500, 500);
  smooth();
  noStroke();
  noiseDetail(4);
}

let a = 0;
let s = TWO_PI/120;

function draw() {
  doLines();
  a+=s;
}

function doLines() {
  background(226,210,184);
   for(let j=50;j<450;j+=25) {
     for(let i=50;i<450;i++) {
      if(j!=50 && j!=440) { //grid
      let step = sin(a)*(sin((450-i)*PI/400.0));
       let swing = j+step*(180.0*noise(a+i/300.0, a+j/300.0,a/10.0)-90.0);
       let dx = randomC()/2;
       let dy = randomC()/2;
       let x = i+dx;
       let y = swing+dy;
       fill(20,150-150*sqrt(sq(dx)+sq(dy))); // pencil effect
       ellipse(x,y,2,2);
    }
  }
 }

}

//pseudo
function randomC() {
  let r = random(0,1);
  let ang = sin(TWO_PI*random(0,1));
  return r*ang;
}
